public static boolean isPowerOfThree(int n) {
    if (n <= 0) {
        return false;
    }
    double logN = Math.log10(n);
    return (Math.floor(logN / Math.log10(3)) == Math.ceil(logN / Math.log10(3)));
}

// Example usage:
int n1 = 27;
